pub fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    debug_assert_eq!(s1.len(), s2.len(), "Input vectors must have equal length");
    debug_assert_eq!(s1.len(), s3.len(), "Input vectors must have equal length");

    let n = s1.len();
    let cap = n.checked_mul(3).expect("3*n must fit in usize");

    let mut res = Vec::with_capacity(cap);
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    res
}